#include <stdio.h>
#include <string.h>
#include <stdbool.h>

/* days in each month for a non‑leap year */
static const int days_in_month[12] = {
    31, 28, 31, 30, 31, 30,
    31, 31, 30, 31, 30, 31
};

/* return true if the given year is a leap year */
static bool is_leap(int year)
{
    return (year % 4 == 0) && (year % 100 != 0 || year % 400 == 0);
}

/* validate a date string of the form YYYY‑MM‑DD */
static bool valid_date(const char *s)
{
    /* length must be exactly 10 */
    if (strlen(s) != 10)
        return false;

    /* positions 4 and 7 must be '-' */
    if (s[4] != '-' || s[7] != '-')
        return false;

    /* all other characters must be decimal digits */
    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) continue;
        if (s[i] < '0' || s[i] > '9')
            return false;
    }

    /* parse year, month and day */
    int year  = (s[0] - '0') * 1000 +
                (s[1] - '0') * 100  +
                (s[2] - '0') * 10   +
                (s[3] - '0');

    int month = (s[5] - '0') * 10 + (s[6] - '0');
    int day   = (s[8] - '0') * 10 + (s[9] - '0');

    /* month must be in the range 1..12 */
    if (month < 1 || month > 12)
        return false;

    /* day must be at least 1 */
    if (day < 1)
        return false;

    /* determine the maximum day for the given month */
    int max_day = days_in_month[month - 1];
    if (month == 2 && is_leap(year))
        max_day = 29;

    /* day must not exceed the maximum for the month */
    if (day > max_day)
        return false;

    return true;
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    if (valid_date(argv[1]))
        puts("VALID");
    else
        puts("INVALID");

    return 0;
}
